/// The function pointers of the commands that are called without an instance.
///
/// [`Self::load`] fills the table. [`crate::Entry`] holds one and calls through it.
#[derive(Copy, Clone)]
pub struct EntryFn {
    /// The pointer to [`vkCreateInstance`](https://docs.vulkan.org/refpages/latest/refpages/source/vkCreateInstance.html), or `None` if it is not loaded.
    pub create_instance: PFN_vkCreateInstance,
    /// The pointer to [`vkEnumerateInstanceExtensionProperties`](https://docs.vulkan.org/refpages/latest/refpages/source/vkEnumerateInstanceExtensionProperties.html), or `None` if it is not loaded.
    pub enumerate_instance_extension_properties: PFN_vkEnumerateInstanceExtensionProperties,
    /// The pointer to [`vkEnumerateInstanceLayerProperties`](https://docs.vulkan.org/refpages/latest/refpages/source/vkEnumerateInstanceLayerProperties.html), or `None` if it is not loaded.
    pub enumerate_instance_layer_properties: PFN_vkEnumerateInstanceLayerProperties,
    /// The pointer to [`vkEnumerateInstanceVersion`](https://docs.vulkan.org/refpages/latest/refpages/source/vkEnumerateInstanceVersion.html), or `None` if it is not loaded.
    pub enumerate_instance_version: PFN_vkEnumerateInstanceVersion,
    /// The pointer to [`vkGetInstanceProcAddr`](https://docs.vulkan.org/refpages/latest/refpages/source/vkGetInstanceProcAddr.html), or `None` if it is not loaded.
    pub get_instance_proc_addr: PFN_vkGetInstanceProcAddr,
}

impl EntryFn {
    /// Asks `get_instance_proc_addr` for every command of the table. A command that it
    /// returns no pointer for is left `None`.
    ///
    /// # Safety
    ///
    /// `get_instance_proc_addr` has to be the `vkGetInstanceProcAddr` of a Vulkan loader or implementation that stays loaded for as long as the table is used.
    ///
    /// # Panics
    ///
    /// Panics if `get_instance_proc_addr` is `None`.
    pub unsafe fn load(get_instance_proc_addr: PFN_vkGetInstanceProcAddr) -> Self {
        let get = get_instance_proc_addr.expect("get_instance_proc_addr must not be null");
        unsafe {
            Self {
                create_instance: crate::load_pfn(get(
                    Instance::null(),
                    c"vkCreateInstance".as_ptr(),
                )),
                enumerate_instance_extension_properties: crate::load_pfn(get(
                    Instance::null(),
                    c"vkEnumerateInstanceExtensionProperties".as_ptr(),
                )),
                enumerate_instance_layer_properties: crate::load_pfn(get(
                    Instance::null(),
                    c"vkEnumerateInstanceLayerProperties".as_ptr(),
                )),
                enumerate_instance_version: crate::load_pfn(get(
                    Instance::null(),
                    c"vkEnumerateInstanceVersion".as_ptr(),
                )),
                get_instance_proc_addr: Some(get),
            }
        }
    }
}

