    pub unsafe fn acquire_full_screen_exclusive_mode_ext_raw(
        &self,
        swapchain: SwapchainKHR,
    ) -> VkResult {
        unsafe {
            (self
                .fp()
                .acquire_full_screen_exclusive_mode_ext
                .expect("vkAcquireFullScreenExclusiveModeEXT is not loaded"))(
                self.handle(),
                swapchain,
            )
        }
    }
